문 9. 다음 C 프로그램의 출력 값은?
#include <stdio.h>
int main()
{
int darr[3][3] = {{1, 2, 3}, {4, 5, 6}, {7, 8, 9}};
int sum1, sum2;
sum1 = *(*darr + 1) + *(*darr + 2);
sum2 = *darr[1] + *darr[2];
printf("%d, %d", sum1, sum2);
}

문 20. 다음 C 프로그램의 출력 값은?
#include <stdio.h>
int recur(int a, int b)
{
if (a <=1)
return a * b;
else
return a * recur(a-1, b+1) + recur(a-1, b);
}
int main()
{
int a=3, b=2;
printf("%d\n", recur(a, b));
}
